solutionCode:
#include <stdio.h>

int aSomaDoArquivo(void) {
    FILE *f = fopen("numeros.txt", "r");
    int n = 0;
    int soma = 0;

    while (fscanf(f, "%d", &n) == 1) {
        soma = soma + n;
    }

    fclose(f);
    return soma;
}
